final class RecoveryService {
    public static function gpsPoint(Actor $a,array $data):array {
        Guard::cap($a,Capabilities::ATT_SELF);
        try{$gps=GpsPointValidator::normalize($data);}catch(\InvalidArgumentException $e){throw new DomainException($e->getMessage(),'gps_invalid',422);}
        $recorded=trim((string)($data['recorded_at']??''));$recorded=$recorded===''?Db::now():Input::utcDateTime($recorded,'GPS recorded_at');
        return Transaction::run(function()use($a,$data,$gps,$recorded){
            $db=Db::wpdb();$att=$db->get_row($db->prepare("SELECT * FROM ".Db::table('attendance')." WHERE company_id=%d AND employee_id=%d AND business_date=%s FOR UPDATE",$a->companyId,$a->employeeId,Db::today()),ARRAY_A);
            if(!$att||!$att['check_in_at']||$att['check_out_at'])throw new DomainException('Active check-in required for GPS tracking.','gps_checkin_required',409);
            GpsDutyPolicy::assertRecordedAt($recorded,$att);
            $utc=new \DateTimeZone('UTC');$recordedAt=new \DateTimeImmutable($recorded,$utc);$earliest=(new \DateTimeImmutable((string)$att['check_in_at'],$utc))->modify('-5 minutes');$latest=(new \DateTimeImmutable('now',$utc))->modify('+10 minutes');if($recordedAt<$earliest||$recordedAt>$latest)throw new DomainException('GPS recorded_at is outside the active attendance window.','gps_recorded_time_invalid',422);
            $branch=(int)$att['branch_id']; if(!$a->hasBranch($branch))throw new DomainException('Attendance branch is outside effective authority.','branch_forbidden',403);
            $visitId=isset($data['field_visit_id'])?(int)$data['field_visit_id']:0;
            if($visitId){$v=$db->get_row($db->prepare("SELECT id FROM ".Db::table('field_visits')." WHERE id=%d AND company_id=%d AND employee_id=%d AND status='in_progress'",$visitId,$a->companyId,$a->employeeId),ARRAY_A);if(!$v)throw new DomainException('Active field visit not found.','field_visit_not_found',404);}
            Db::mustInsert($db,Db::table('gps_points'),['company_id'=>$a->companyId,'branch_id'=>$branch,'employee_id'=>$a->employeeId,'attendance_id'=>(int)$att['id'],'field_visit_id'=>$visitId?:null,'latitude'=>$gps['latitude'],'longitude'=>$gps['longitude'],'accuracy_m'=>$gps['accuracy_m'],'source'=>$gps['source'],'recorded_at'=>$recorded,'created_at'=>Db::now()]);
            return ['id'=>(int)$db->insert_id,'recorded_at'=>$recorded]+$gps;
        });
    }
    public static function gpsRoute(Actor $a,?int $employeeId,string $from,string $to):array {
        $employeeId=$employeeId?:$a->employeeId;$db=Db::wpdb();$e=$db->get_row($db->prepare("SELECT id,assigned_branch_id FROM ".Db::table('employees')." WHERE id=%d AND company_id=%d AND status='active'",$employeeId,$a->companyId),ARRAY_A);if(!$e)throw new DomainException('Employee not found.','employee_not_found',404);
        $self=$employeeId===$a->employeeId;
        if($self)Guard::cap($a,Capabilities::ATT_SELF);else {Guard::cap($a,Capabilities::GPS_TEAM_VIEW);HierarchyScope::assertCanViewEmployee($a,$employeeId);}
        [$from,$to]=Input::utcDateTimeRange($from,$to,'GPS route period');
        $sql="SELECT id,branch_id,employee_id,attendance_id,field_visit_id,latitude,longitude,accuracy_m,source,recorded_at FROM ".Db::table('gps_points')." WHERE company_id=%d AND employee_id=%d AND recorded_at BETWEEN %s AND %s";$args=[$a->companyId,$employeeId,$from,$to];
        $sql.=" ORDER BY recorded_at,id";return (array)$db->get_results($db->prepare($sql,...$args),ARRAY_A);
    }
    public static function gpsTeam(Actor $a,?int $branchId=null):array {
        Guard::cap($a,Capabilities::GPS_TEAM_VIEW);$db=Db::wpdb();$ids=HierarchyScope::visibleEmployeeIds($a,$branchId);if(!$ids)return[];$ph=implode(',',array_fill(0,count($ids),'%d'));$args=array_merge([$a->companyId,Db::today()],$ids);
        $sql="SELECT e.id employee_id,e.employee_code,e.full_name,e.designation_code,e.reporting_designation_code,e.assigned_branch_id,a.id attendance_id,a.check_in_at,a.check_out_at,a.status attendance_status,g.latitude,g.longitude,g.accuracy_m,g.recorded_at latest_gps_at FROM ".Db::table('employees')." e LEFT JOIN ".Db::table('attendance')." a ON a.company_id=e.company_id AND a.employee_id=e.id AND a.business_date=%s LEFT JOIN ".Db::table('gps_points')." g ON g.id=(SELECT gp.id FROM ".Db::table('gps_points')." gp WHERE gp.company_id=e.company_id AND gp.employee_id=e.id AND gp.attendance_id=a.id ORDER BY gp.recorded_at DESC,gp.id DESC LIMIT 1) WHERE e.company_id=%d AND e.status='active' AND e.id IN ({$ph}) ORDER BY e.full_name";
        $args2=array_merge([Db::today(),$a->companyId],$ids);$rows=(array)$db->get_results($db->prepare($sql,...$args2),ARRAY_A);foreach($rows as&$r){$att=['business_date'=>Db::today(),'check_in_at'=>$r['check_in_at'],'check_out_at'=>$r['check_out_at']];$r=array_merge($r,GpsDutyPolicy::state($att));$r['reporting_category']=HierarchyScope::reportingCategoryForCode((string)$r['designation_code'],(string)($r['reporting_designation_code']??''));}unset($r);return$rows;
    }
    public static function holidays(Actor $a,?int $branchId,string $from,string $to):array {
        Guard::any($a,[Capabilities::LEAVE_SELF,Capabilities::LEAVE_MANAGE]);$branchId=$branchId?:$a->assignedBranchId;if($branchId&&!$a->hasBranch($branchId))throw new DomainException('Branch is outside effective authority.','branch_forbidden',403);
        $from=trim($from);$to=trim($to);if($from==='')$from=current_time('Y').'-01-01';if($to==='')$to=current_time('Y').'-12-31';[$from,$to]=Input::dateRange($from,$to,'Holiday period');
        $db=Db::wpdb();return (array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('holidays')." WHERE company_id=%d AND active=1 AND (branch_id IS NULL OR branch_id=%d) AND holiday_date BETWEEN %s AND %s ORDER BY holiday_date,id",$a->companyId,$branchId,$from,$to),ARRAY_A);
    }
    private static function employeeForAccess(Actor $a,int $employeeId,string $peerCap):array {
        $db=Db::wpdb();$e=$db->get_row($db->prepare("SELECT id,assigned_branch_id,employee_code,full_name FROM ".Db::table('employees')." WHERE id=%d AND company_id=%d",$employeeId,$a->companyId),ARRAY_A);if(!$e)throw new DomainException('Employee not found.','employee_not_found',404);
        if($employeeId!==$a->employeeId){Guard::branch($a,(int)$e['assigned_branch_id'],$peerCap);HierarchyScope::assertCanViewEmployee($a,$employeeId);}return $e;
    }
    public static function employeeDocuments(Actor $a,int $employeeId):array {$readCap=$a->can(Capabilities::EMP_DOCUMENT_VIEW)?Capabilities::EMP_DOCUMENT_VIEW:Capabilities::EMP_DOCUMENT_MANAGE;self::employeeForAccess($a,$employeeId,$readCap);$db=Db::wpdb();$rows=(array)$db->get_results($db->prepare("SELECT id,employee_id,attachment_id,private_file_id,document_type,title,status,uploaded_by,created_at,updated_at FROM ".Db::table('employee_documents')." WHERE company_id=%d AND employee_id=%d AND status='active' ORDER BY id DESC",$a->companyId,$employeeId),ARRAY_A);foreach($rows as&$row){$row['url']=!empty($row['private_file_id'])?\ExcelHerbal\ERP7\Organization\DocumentVault::url('employee',$employeeId,(int)$row['id']):null;$row['requires_auth']=true;$row['migration_required']=empty($row['private_file_id']);}unset($row);return$rows;}
    public static function addEmployeeDocument(Actor $a,int $employeeId,array $data):array {self::employeeForAccess($a,$employeeId,Capabilities::EMP_DOCUMENT_MANAGE);throw new DomainException('Public media linking is disabled. Use the private document upload endpoint.','private_document_upload_required',409);}
    public static function readNotification(Actor $a,int $id):array {Guard::cap($a,Capabilities::COMM_VIEW);$db=Db::wpdb();$t=Db::table('notifications');$r=$db->get_row($db->prepare("SELECT id,read_at FROM {$t} WHERE id=%d AND company_id=%d AND employee_id=%d",$id,$a->companyId,$a->employeeId),ARRAY_A);if(!$r)throw new DomainException('Notification not found.','notification_not_found',404);if(!$r['read_at'])Db::mustUpdate($db,$t,['read_at'=>Db::now()],['id'=>$id]);return ['id'=>$id,'read'=>true];}
    public static function readAllNotifications(Actor $a):array {Guard::cap($a,Capabilities::COMM_VIEW);$db=Db::wpdb();$sql=$db->prepare("UPDATE ".Db::table('notifications')." SET read_at=%s WHERE company_id=%d AND employee_id=%d AND read_at IS NULL",Db::now(),$a->companyId,$a->employeeId);$count=Db::mustQuery($db,$sql);return ['updated'=>$count];}
    public static function acknowledgeAnnouncement(Actor $a,int $id):array {Guard::cap($a,Capabilities::COMM_VIEW);$db=Db::wpdb();$ids=$a->branchIds?implode(',',array_map('intval',$a->branchIds)):'0';$r=$db->get_row($db->prepare("SELECT id FROM ".Db::table('announcements')." WHERE id=%d AND company_id=%d AND status='published' AND (branch_id IS NULL OR branch_id IN ({$ids}))",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Announcement not found.','announcement_not_found',404);$t=Db::table('announcement_acknowledgements');$sql=$db->prepare("INSERT INTO {$t}(company_id,announcement_id,employee_id,acknowledged_at) VALUES(%d,%d,%d,%s) ON DUPLICATE KEY UPDATE acknowledged_at=acknowledged_at",$a->companyId,$id,$a->employeeId,Db::now());Db::mustQuery($db,$sql);return ['id'=>$id,'acknowledged'=>true];}
    public static function registerPushDevice(Actor $a,array $data):array {Guard::cap($a,Capabilities::COMM_VIEW);$token=trim((string)($data['token']??''));$platform=strtolower(trim((string)($data['platform']??'android')));$deviceName=trim((string)($data['device_name']??''));if(!in_array($platform,['android','ios'],true))throw new DomainException('Push platform is invalid.','push_platform_invalid',422);if(strlen($deviceName)>190)throw new DomainException('Push device name is too long.','push_device_invalid',422);try{$sealed=PushTokenCrypto::protect($token,wp_salt('auth'));}catch(\Throwable $e){throw new DomainException($e->getMessage(),'push_token_invalid',422);}$db=Db::wpdb();$t=Db::table('push_devices');$existing=(int)$db->get_var($db->prepare("SELECT id FROM {$t} WHERE token_hash=%s",$sealed['hash']));$row=['company_id'=>$a->companyId,'employee_id'=>$a->employeeId,'platform'=>$platform,'token_hash'=>$sealed['hash'],'token_ciphertext'=>$sealed['ciphertext'],'token_iv'=>$sealed['iv'],'token_tag'=>$sealed['tag'],'device_name'=>$deviceName?:null,'active'=>1,'last_seen_at'=>Db::now(),'updated_at'=>Db::now()];if($existing){Db::mustUpdate($db,$t,$row,['id'=>$existing]);$id=$existing;}else{unset($row['updated_at']);$row['created_at']=Db::now();Db::mustInsert($db,$t,$row);$id=(int)$db->insert_id;}return ['id'=>$id,'active'=>true];}
    public static function deactivatePushDevice(Actor $a,array $data):array {Guard::cap($a,Capabilities::COMM_VIEW);$db=Db::wpdb();$t=Db::table('push_devices');$id=(int)($data['id']??0);$token=trim((string)($data['token']??''));if(!$id&&$token==='')throw new DomainException('Push device id or token required.','push_device_required',422);if($id){$r=$db->get_row($db->prepare("SELECT id FROM {$t} WHERE id=%d AND company_id=%d AND employee_id=%d",$id,$a->companyId,$a->employeeId),ARRAY_A);}else{$hash=hash('sha256',$token);$r=$db->get_row($db->prepare("SELECT id FROM {$t} WHERE token_hash=%s AND company_id=%d AND employee_id=%d",$hash,$a->companyId,$a->employeeId),ARRAY_A);}if(!$r)throw new DomainException('Push device not found.','push_device_not_found',404);Db::mustUpdate($db,$t,['active'=>0,'updated_at'=>Db::now()],['id'=>(int)$r['id']]);return ['id'=>(int)$r['id'],'active'=>false];}
    private static function taskEmployee(Actor $a,int $employeeId):array {$db=Db::wpdb();$e=$db->get_row($db->prepare("SELECT id,assigned_branch_id FROM ".Db::table('employees')." WHERE id=%d AND company_id=%d AND status='active'",$employeeId,$a->companyId),ARRAY_A);if(!$e)throw new DomainException('Assigned employee not found.','employee_not_found',404);Guard::branch($a,(int)$e['assigned_branch_id'],Capabilities::COMM_MANAGE);HierarchyScope::assertCanViewEmployee($a,$employeeId);return $e;}
    public static function createTask(Actor $a,array $data):array {Guard::cap($a,Capabilities::COMM_MANAGE);$employee=(int)($data['assigned_employee_id']??0);$e=self::taskEmployee($a,$employee);$title=trim((string)($data['title']??''));$type=trim((string)($data['type']??'general'))?:'general';$entityType=trim((string)($data['entity_type']??''))?:null;$entityId=isset($data['entity_id'])?(int)$data['entity_id']:null;$entityId=$entityId&&$entityId>0?$entityId:null;$due=Input::optionalUtcDateTime((string)($data['due_at']??''),'Task due_at',true);if($title==='')throw new DomainException('Task title required.','task_title_required',422);if(strlen($title)>190||strlen($type)>60||($entityType!==null&&strlen($entityType)>60))throw new DomainException('Task text field is too long.','task_invalid',422);return Transaction::run(function()use($a,$employee,$e,$title,$type,$entityType,$entityId,$due){$db=Db::wpdb();Db::mustInsert($db,Db::table('tasks'),['company_id'=>$a->companyId,'branch_id'=>(int)$e['assigned_branch_id'],'assigned_employee_id'=>$employee,'type'=>$type,'title'=>$title,'entity_type'=>$entityType,'entity_id'=>$entityId,'status'=>'open','due_at'=>$due,'created_at'=>Db::now()]);$id=(int)$db->insert_id;self::notifyTask($a,$employee,$id,$title,'task_assigned');Audit::add($a,'task.create','task',$id,['assigned_employee_id'=>$employee]);return ['id'=>$id,'status'=>'open','assigned_employee_id'=>$employee,'due_at'=>$due];});}
    public static function assignTask(Actor $a,int $id,int $employeeId,bool $reassign=false):array {Guard::cap($a,Capabilities::COMM_MANAGE);$e=self::taskEmployee($a,$employeeId);return Transaction::run(function()use($a,$id,$employeeId,$e,$reassign){$db=Db::wpdb();$t=Db::table('tasks');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Task not found.','task_not_found',404);if((int)($r['branch_id']??0)>0)Guard::branch($a,(int)$r['branch_id'],Capabilities::COMM_MANAGE);if($r['status']==='completed')throw new DomainException('Completed task cannot be assigned.','task_completed',409);if(!$reassign&&(int)$r['assigned_employee_id']>0&&(int)$r['assigned_employee_id']!==$employeeId)throw new DomainException('Task is already assigned; use reassign.','task_already_assigned',409);Db::mustUpdate($db,$t,['assigned_employee_id'=>$employeeId,'branch_id'=>(int)$e['assigned_branch_id']],['id'=>$id]);self::notifyTask($a,$employeeId,$id,(string)$r['title'],$reassign?'task_reassigned':'task_assigned');Audit::add($a,$reassign?'task.reassign':'task.assign','task',$id,['assigned_employee_id'=>$employeeId]);return ['id'=>$id,'assigned_employee_id'=>$employeeId,'status'=>$r['status']];});}
    private static function notifyTask(Actor $a,int $employeeId,int $taskId,string $title,string $type):void {$db=Db::wpdb();Db::mustInsert($db,Db::table('notifications'),['company_id'=>$a->companyId,'employee_id'=>$employeeId,'type'=>$type,'title'=>'Task: '.$title,'body'=>null,'entity_type'=>'task','entity_id'=>$taskId,'read_at'=>null,'created_at'=>Db::now()]);}
    public static function appVersionPolicy(?Actor $a,int $clientBuild=0):array {$db=Db::wpdb();$companyId=$a?->companyId;if(!$companyId)$companyId=(int)$db->get_var("SELECT id FROM ".Db::table('companies')." WHERE status='active' ORDER BY id LIMIT 1");if(!$companyId)return AppVersionPolicy::project([],$clientBuild);$keys=['app.android.minimum_build','app.android.latest_build','app.android.minimum_version','app.android.latest_version','app.android.update_url','app.android.update_message'];$in="'".implode("','",array_map('esc_sql',$keys))."'";$rows=(array)$db->get_results($db->prepare("SELECT setting_key,setting_value FROM ".Db::table('settings')." WHERE company_id=%d AND setting_key IN ({$in})",$companyId),ARRAY_A);$map=[];foreach($rows as$r)$map[(string)$r['setting_key']]=(string)$r['setting_value'];return AppVersionPolicy::project($map,$clientBuild);}
    public static function updateAppVersionPolicy(Actor $a,array $data):array {
        Guard::cap($a,Capabilities::ACCESS_MANAGE);
        $allowed=['minimum_build','latest_build','minimum_version','latest_version','update_url','message'];
        $map=['minimum_build'=>'app.android.minimum_build','latest_build'=>'app.android.latest_build','minimum_version'=>'app.android.minimum_version','latest_version'=>'app.android.latest_version','update_url'=>'app.android.update_url','message'=>'app.android.update_message'];
        $current=self::appVersionPolicy($a,0);
        $normalised=[];
        foreach(['minimum_build','latest_build'] as $key){
            if(!array_key_exists($key,$data))continue;
            $raw=trim((string)$data[$key]);
            if($raw===''||!ctype_digit($raw))throw new DomainException($key.' must be a non-negative integer.','app_version_policy_invalid',422);
            $normalised[$key]=(string)(int)$raw;
        }
        $minimum=array_key_exists('minimum_build',$normalised)?(int)$normalised['minimum_build']:(int)$current['minimum_build'];
        $latest=array_key_exists('latest_build',$normalised)?(int)$normalised['latest_build']:(int)$current['latest_build'];
        if($latest>0&&$latest<$minimum)throw new DomainException('latest_build cannot be lower than minimum_build.','app_version_policy_invalid',422);
        foreach(['minimum_version','latest_version'] as $key){if(array_key_exists($key,$data)){ $value=trim((string)$data[$key]);if(strlen($value)>60)throw new DomainException($key.' is too long.','app_version_policy_invalid',422);$normalised[$key]=$value;}}
        if(array_key_exists('update_url',$data)){$url=trim((string)$data['update_url']);if($url!==''&&(!filter_var($url,FILTER_VALIDATE_URL)||!in_array(strtolower((string)parse_url($url,PHP_URL_SCHEME)),['http','https'],true)))throw new DomainException('update_url must be an HTTP(S) URL.','app_version_policy_invalid',422);$normalised['update_url']=$url;}
        if(array_key_exists('message',$data)){$message=trim((string)$data['message']);if(strlen($message)>1000)throw new DomainException('Update message is too long.','app_version_policy_invalid',422);$normalised['message']=$message;}
        $db=Db::wpdb();$t=Db::table('settings');
        foreach($allowed as$k){if(!array_key_exists($k,$normalised))continue;$key=$map[$k];$value=(string)$normalised[$k];$sql=$db->prepare("INSERT INTO {$t}(company_id,setting_key,setting_value,updated_by,updated_at) VALUES(%d,%s,%s,%d,%s) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by),updated_at=VALUES(updated_at)",$a->companyId,$key,$value,$a->employeeId,Db::now());Db::mustQuery($db,$sql);}
        Audit::add($a,'app.version_policy.update','company',$a->companyId,$normalised);
        return self::appVersionPolicy($a,(int)($data['client_build']??0));
    }
}
